import{_ as t,o as a,c as s,a2 as n}from"./chunks/framework.hw3Av5Vn.js";const u=JSON.parse('{"title":"Installing","description":"","frontmatter":{},"headers":[],"relativePath":"INSTALLING.md","filePath":"INSTALLING.md"}'),o={name:"INSTALLING.md"};function i(l,e,r,h,d,p){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="installing" tabindex="-1">Installing <a class="header-anchor" href="#installing" aria-label="Permalink to &quot;Installing&quot;">​</a></h1><p>llamatron runs in a terminal on a Mac, and on Linux for everything but FluidSynth&#39;s installer. This page covers installing llamatron, and one optional component: FluidSynth, which plays every demo with no synthesizer of your own. When it&#39;s installed, <a href="./GETTING_STARTED">Getting Started</a> is the next page.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li>git</li><li>Python 3, which macOS and most Linux systems include, for the small tools beside llamatron</li><li>Rust, which the setup offers to install</li><li>A terminal at least 80 columns wide and 24 rows tall. llamatron draws with bold, dim, reverse video and box characters, so it suits any colour scheme.</li></ul><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><p>Clone the repository and run the setup script from the project folder:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git clone https://github.com/mpdehaan/llamatron.git</span></span>
<span class="line"><span>cd llamatron</span></span>
<span class="line"><span>sh setup.sh</span></span></code></pre></div><p>The script makes a small Python environment in the folder <code>.venv</code> for the development tools, then builds llamatron with <code>sh build.sh</code>, which checks for Rust and offers to install it first, installing nothing without your yes (<a href="./BUILDING_THE_BACKEND">Building llamatron</a>). After a <code>git pull</code>, run <code>sh build.sh</code> again to build the new code.</p><p>To install Rust yourself before running the setup, use rustup, the Rust project&#39;s own installer, which puts Rust in your home folder and needs no password:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>curl --proto &#39;=https&#39; --tlsv1.2 -sSf https://sh.rustup.rs | sh</span></span></code></pre></div><p>Then open a new terminal, so that it finds <code>cargo</code>, and run <code>sh setup.sh</code>.</p><p>From the project folder, <code>./llamatron.sh</code> runs llamatron, and every other script in <code>user_scripts/</code> and <code>internal_tools/</code> runs from there too.</p><h2 id="fluidsynth-optional" tabindex="-1">FluidSynth (Optional) <a class="header-anchor" href="#fluidsynth-optional" aria-label="Permalink to &quot;FluidSynth (Optional)&quot;">​</a></h2><p>FluidSynth is a free software synthesizer, and it is the quickest way to hear llamatron: with it, every demo plays as it comes, with no synthesizer of your own, no DAW and no MIDI setup, and a song can be exported as a WAV file. Install it now if you want to hear the demos right away, or if you have no synthesizer or DAW of your own set up; skip it if you will play everything through your own instruments. On a Mac, from the project folder:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sh user_scripts/install_fluidsynth.sh</span></span></code></pre></div><p><a href="./FLUIDSYNTH">FluidSynth</a> describes what the script installs, how the tracker uses FluidSynth, and when to use your own instruments instead. To check that it works, open a demo and play it:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./llamatron.sh examples/learning/02_pachelbel.yml</span></span></code></pre></div><p>Press <code>A</code> for Arrange, move to the top left corner with the arrows, where <code>▶ song</code> shows, and press <code>Space</code>.</p>`,18)])])}const m=t(o,[["render",i]]);export{u as __pageData,m as default};
